from model import Summary

def read_header(data,start):
 return data[start],start+1,0

def fits(length,limit):
 return length<=limit

def checksum(data):
 return sum(data)%256

def run(data,limit):
 frames=[];cursor=0;error=0
 while cursor<len(data) and error==0:
  header=data[cursor]
  if header==255:
   cursor+=1
   continue
  if header==254:
   if len(data)-cursor<3:
    error=1
    continue
   length=data[cursor+1]|(data[cursor+2]<<8)
   payload=cursor+3
  else:
   length,payload,header_error=read_header(data,cursor)
   if header_error:
    error=header_error
    continue
  if not fits(length,limit):
   error=3
  elif len(data)-payload<length+1:
   error=1
  else:
   value=data[payload:payload+length]
   if checksum(value)!=data[payload+length]:
    error=2
   else:
    frames.append(value)
    cursor=payload+length+1
 return Summary(frames,cursor,error)

